/**
* Run every case against `factory`. With a harness each case registers as one
* test; without one the cases run sequentially and the first failure throws.
*/
async function runContentStorageConformance(factory, harness) {
	if (harness) {
		for (const item of CONTENT_STORAGE_CONFORMANCE_CASES) harness.test(item.name, () => item.run(factory));
		return;
	}
	for (const item of CONTENT_STORAGE_CONFORMANCE_CASES) try {
		await item.run(factory);
	} catch (error) {
		throw new ConformanceFailure(`${item.name}: ${error instanceof Error ? error.message : String(error)}`, { cause: error });
	}
}
